#!/usr/bin/env python3
"""Builds ../RESULTS_H2.md from the JSON files in ../results. Every number quoted for Rev H2 is in this file or in the JSON it is
built from. Run after tests_mech.py (quick), gate_like.py, hang.py, statics.py, dock_mc.py, mission.py and bom_revH2.py."""
import os, json, math
HERE = os.path.dirname(os.path.abspath(__file__)); RES = os.path.join(HERE, '..', 'results')
J = lambda n: json.load(open(os.path.join(RES, n + '.json')))
mech, stat, dock, mis, bom, hang, gate = J('mech'), J('statics'), J('dock_mc'), J('mission'), J('bom_revH2'), J('hang'), J('gate_like')
L = []; w = L.append


def table(head, rows):
    w('| ' + ' | '.join(head) + ' |'); w('|' + '|'.join(['---'] * len(head)) + '|')
    for r in rows: w('| ' + ' | '.join(str(c) for c in r) + ' |')
    w('')


def tally(rows):
    return '%d of %d' % (sum(1 for r in rows if r['ok']), len(rows))


yn = lambda b: 'pass' if b else 'FAIL'
ob = mech['obstacles']; wl = mech['wet_leaves_steps']; gr = mech['grades']; meta = mech['meta']
R = meta['ROBOT']; s = bom['summary']
w('# Bin Tug Rev H2: results'); w('')
w('Generated by `sim/make_results_md.py` on %s from the JSON files in `results/`. **Nothing here has been built or bench-tested, and nothing here is a MuJoCo or SITL result.**' % meta['date'])
w('The models are first-order (`sim/dyn.py`): one rigid body with x, z, pitch and roll, penalty wheel contact and stick-slip tyre friction. The bin is welded to the robot and there is no yaw. '
  'The other agent\'s MuJoCo gate is the stricter test and Rev H2 has not been through it: see `docs/TESTS_AND_SIMULATIONS.md`.'); w('')

w('## 1. Robot'); w('')
full = next(r for r in mech['loads'] if r['bin'].startswith('ESE 240 SL') and r['fill'] == 1.0); unl = mech['loads'][0]
table(['Item', 'Value'], [
    ['Length x width x height', '%.2f x %.2f x %.2f m' % (R['nose_tip_x'] - R['leg_tip_x'], R['width'], R['height'])],
    ['Drive track / wheel radius', '%.2f m / %.3f m' % (R['drive_track'], R['drive_r'])],
    ['Nose castors', 'radius %.3f m at x = %.2f m, track %.2f m' % (R['nose_r'], R['nose_x'], R['nose_track'])],
    ['Anti-tip wheels', 'x = %.2f m, track %.2f m, %.0f mm off the ground' % (R['tail_x'], R['tail_track'], R['tail_gap'] * 1000)],
    ['Clear width between rails / funnel mouth', '%.2f m / %.2f m' % (R['leg_inner_gap'], R['funnel_mouth'])],
    ['Comb', '%.0f mm wide, self-aligning (yaw +/-%.0f deg, roll +/-%.0f deg), travel %.2f to %.2f m' % (R['comb_width'] * 1000, R['comb_yaw_deg'], R['comb_roll_deg'], R['comb_z_min'], R['comb_z_max'])],
    ['Rest pad', '%.0f mm below the comb, face %.0f mm behind the comb seat line, depth slots +/-%.0f mm' % (R['pad_drop'] * 1000, R['pad_setback'] * 1000, R['pad_adjust'] * 1000)],
    ['Mast centre / bin front wall / battery centre', 'x = %.2f / %.2f / %.2f m from the drive axle' % (R['mast_x'], R['pad_x'], R['batt_x'])],
    ['Robot mass, centre of gravity', '%.1f kg, x %.3f m, z %.3f m' % (unl['mass_kg'], unl['cg_x'], unl['cg_z'])],
    ['With a full 240 L bin (110 kg)', '%.1f kg, CG x %.3f m, z %.3f m; %.1f kg on the drive wheels, %.1f kg on the nose castors' % (full['mass_kg'], full['cg_x'], full['cg_z'], full['drive_kg'], full['nose_kg'])]])

w('## 2. How the bin hangs from the comb (`hang.py`)'); w('')
w('Static geometry. Wall positions are scaled from manufacturer drawings, so they must be measured on the real bins (test B1). Pad face %d mm behind the comb seat line, %d mm below it; target wheel clearance %d mm.'
  % (hang['pad_setback_default_mm'], hang['pad_drop_mm'], hang['wheel_clear_target_mm'])); w('')
table(['Bin', 'Front wall behind the seat line at pad height mm', 'Hang deg', 'Wheel drop mm', 'Clearance at 100 mm lift mm', 'Pad force, full bin N', 'Within lift travel'],
      [[r['bin'], r['wall_setback_mm'], r['hang_deg'], r['wheel_drop_mm'], r['clearance_at_100mm_lift_mm'], r['pad_force_full_N'], yn(r['within_travel'])] for r in hang['as_designed']])
w('Largest gap between wall and pad that the lift travel can still absorb (firmware FH1 lifts until the wheels are clear):'); w('')
table(['Bin', 'Largest gap mm', 'Hang at that gap deg'], [[r['bin'], r['largest_gap_mm'], r['hang_deg']] for r in hang['travel_limit']])
o = hang['other_agent_revH_model']
w('The other agent\'s Rev H test, reproduced with their assumptions (%d mm front-wall taper, pad %s): swing at the pad %d mm, hang %.1f deg, wheel drop %d mm. Their MuJoCo result: %s. %s.'
  % (o['front_wall_taper_mm'], o['pad'], o['swing_at_pad_mm'], o['hang_deg'], o['wheel_drop_mm'], o['their_mujoco_result'], o['drawings_show'][0].upper() + o['drawings_show'][1:])); w('')

w('## 3. Against the other agent\'s frozen gate (`gate_like.py`)'); w('')
w('Thresholds from `reference/other_agent/revG/sim/cg/CRITERIA_FROZEN.md`. **Indications only**: this is not the gate model. Items that need contact or yaw physics were not run.'); w('')
g8 = next(r for r in gate['G8'] if r['bin_kg'] == 110.0 and r['bin_cg_model'] == 'gate')
g2 = gate['G2']; g3 = gate['G3']; g4 = gate['G4']
g3a = [r for r in g3 if r['h_mm'] == 40 and r['where'] == 'one side']; g3b = [r for i, r in enumerate(g3) if r['h_mm'] == 40 and r['where'] != 'one side' and i < 8]
table(['Gate item', 'Threshold', 'Rev H2 in this model', 'Status'], [
    ['G1 grab Monte Carlo', '>=28/30 per bin, >=87/90, 0 false holds', 'not run (contact physics)', 'OPEN: needs MuJoCo'],
    ['G2 climb 12 %, full 240 L', '5 m in <=25 s at mu 0.30/0.25/0.22; hold creep <0.05 m', '%s; %.1f to %.1f s; creep up to %.3f m' % (tally(g2), min(r['t_5m_s'] for r in g2), max(r['t_5m_s'] for r in g2), max(r['hold_creep_m'] for r in g2)), 'indication: pass'],
    ['G3(a) 40 mm step, one side', 'reach 4.5 m in <=25 s', tally(g3a), 'indication: pass (no yaw in this model)'],
    ['G3(b) 40 mm step, full width', 'reach 4.5 m in <=25 s', tally(g3b), 'indication: pass here, but MuJoCo stalls every design on this item'],
    ['G4 e-stop, 12 % down, mu 0.30, 0.5 m/s', 'stop <=0.5 m, slide <0.05 m', '; '.join('%s leading %.3f m' % (r['leading'], r['stop_m']) for r in g4 if abs(r['v_at_brake'] - 0.5) < 0.06), 'indication: pass'],
    ['G5 carry and 180 deg pivot', 'swept <=3.2 m', 'geometry only: pivot circle %.2f m' % mis['turning']['Rev H2 pivot']['u_turn_width_m'], 'OPEN: needs MuJoCo'],
    ['G6 set-down, 18 cases', 'all', 'not run', 'OPEN: needs MuJoCo'],
    ['G7 time-step repeat', 'same result', 'not run', 'OPEN: needs MuJoCo'],
    ['G8 static loads and tip angles', 'drive >=100 N each, castors >=50 N, tips >=20 deg', 'castors >=%d N, drive >=%d N; lateral %.1f, forward %.1f, rear %.1f deg; castor lift-off %.1f deg'
     % (min(p['castors_N'] for p in g8['poses'].values()), min(min(v for k, v in p.items() if k.startswith('drive')) for p in g8['poses'].values()), g8['tips']['lateral_deg'], g8['tips']['forward_over_castors_deg'],
        g8['tips']['rear_onto_antitip_wheels_deg'], g8['tips']['castor_liftoff_about_drive_axle_deg']), 'hand calc: pass'],
    ['G9 mass', '<=120 kg', '%.1f kg (donor AGM %.1f, LiFePO4 %.1f)' % (gate['G9']['mass_kg'], gate['G9']['with_donor_agm_kg'], gate['G9']['with_lifepo4_kg']), 'pass']])
w('Step detail, full 240 L at 0.5 m/s (the last two rows are the 40 mm step repeated at friction 0.45, as ordered in `gate_like.py`):'); w('')
table(['Step mm', 'Friction', 'Where', 'Leading', 'Reached m', 'Time s', 'Result'], [[r['h_mm'], 0.45 if i >= 8 else 0.6, r['where'], r['leading'], r['reached_m'], r['t_s'], yn(r['ok'])] for i, r in enumerate(g3)])
table(['E-stop', 'Leading', 'Speed at brake m/s', 'Stop m', 'Slide after stop m', 'Result'], [[r['test'], r['leading'], r['v_at_brake'], r['stop_m'], r['slide_after_stop_m'], yn(r['ok'])] for r in g4])
table(['Bin kg', 'Bin CG model', 'Mass kg', 'CG x m', 'CG z m', 'Lateral tip deg', 'Castor lift-off deg', '>=20 deg target', 'Friction needed on 12 % (their method)', 'Torque per wheel N m'],
      [[r['bin_kg'], {'gate': 'gate', 'mine': 'params'}.get(r['bin_cg_model'], r['bin_cg_model']), r['mass_kg'], r['cg_x'], r['cg_z'], r['tips']['lateral_deg'], r['tips']['castor_liftoff_about_drive_axle_deg'], 'n/a (no bin)' if r['castor_liftoff_target_met'] is None else yn(r['castor_liftoff_target_met']), r['mu_req_12pct_their_method'], r['torque_per_wheel_12pct_Nm']] for r in gate['G8']])
w('"gate" is the other agent\'s bin centre of gravity; "params" is the higher one used in `params.bin_cg`. The castor lift-off target is met with theirs and missed by about 1 deg with mine at 110 kg: tilt-table test B7 settles it. '
  'The sideways tip angle here is taken about the line from drive wheel to castor (the stricter method); section 6 takes it about the drive track, as the earlier reports did.'); w('')

w('## 4. Obstacles (`tests_mech.py quick`)'); w('')
w('Loads: unladen, empty 240 L, full 240 L (110 kg), full 140 L (70 kg). Torque limit 60 N m per wheel.'); w('')
w('### 4.1 Square step up, full width'); w('')
rows = []
for mu in (0.6, 0.45, 0.3):
    src = wl if mu == 0.3 else ob
    for h in sorted(set(r['h_mm'] for r in src if r['kind'] == 'step' and r['h_mm'] > 0 and not r['onesided'] and r['mu'] == mu and r['t_lim'] == 60.0)):
        for v in (0.5, 0.8):
            rr = [r for r in src if r['kind'] == 'step' and not r['onesided'] and r['mu'] == mu and r['h_mm'] == h and r['v'] == v and r['t_lim'] == 60.0]
            if rr: rows.append([mu, h, v, tally(rr), ', '.join(r['load'] for r in rr if not r['ok']) or '-'])
table(['Friction', 'Step mm', 'Speed m/s', 'Pass', 'Loads that stall'], rows)
w('### 4.2 Other obstacles'); w('')
kind_of = lambda r: r['kind'] if r['kind'] != 'step' else ('step up' if r['h_mm'] > 0 else 'step down')
oth = [r for r in ob if kind_of(r) != 'step up' or r['onesided']]; rows = []
for kind, one in sorted(set((kind_of(r), r['onesided']) for r in oth)):
    for h in sorted(set(abs(r['h_mm']) for r in oth if kind_of(r) == kind and r['onesided'] == one)):
        rr = [r for r in oth if kind_of(r) == kind and r['onesided'] == one and abs(r['h_mm']) == h]
        fullr = [r['comb_load_factor'] for r in rr if r['load'].startswith('full') and r['comb_load_factor'] is not None]
        rows.append([{'pothole': 'trench' if not one else 'pothole'}.get(kind, kind), 'one side' if one else 'full width', h, tally(rr), max(fullr) if fullr else '-'])
table(['Obstacle', 'Where', 'Size mm', 'Pass (0.5 and 0.8 m/s)', 'Peak lip load factor, full bins'], rows)
gaps = [r['lip_gap_mm'] for r in ob + wl if r.get('lip_gap_mm') is not None]
w('Largest computed gap between lip and comb in any run: %.1f mm (computed after the fact; the bin is welded in this model, so it cannot show a bin jumping off the comb). '
  'The lip load factor is the peak comb force divided by the bin\'s weight with rigid tyres, so it is likely pessimistic.' % max(gaps)); w('')

w('## 5. Grades'); w('')
rows = []
for mode in sorted(set(r['mode'] for r in gr)):
    rr = [r for r in gr if r['mode'] == mode]
    rows.append([mode, tally(rr), ', '.join(sorted(set('%s %s%% mu %s' % (r['load'], r['grade_pct'], r['mu']) for r in rr if not r['ok']))) or '-'])
table(['Case', 'Pass', 'Failures'], rows)
table(['Load', 'Friction needed to hold on 12 %, nose downhill', 'Nose uphill', 'On 7.5 %, nose downhill'], [[('%s, fill %.0f %%' % (r['bin'], r['fill'] * 100)) if r['bin'] != 'none' else 'unladen', r['mu_hold_12pct_nose_down'], r['mu_hold_12pct_nose_up'], r['mu_hold_7p5pct_nose_down']]
                                                                                                         for r in mech['loads'] if r['fill'] in (0.0, 1.0)][:9])

w('## 6. Statics (`statics.py`)'); w('')
table(['Bin', 'Gross kg', 'Comb mm', 'Mast moment N m', 'Lift force on rollers N', 'Margin, 4 kN actuator', 'Margin, 3 kN'],
      [[r['bin'], r['gross_kg'], r['comb_mm'], r['mast_moment_Nm'], r['lift_force_rollers_N'], r['actuator_margin_rollers'], r['actuator_margin_rollers_3kN']] for r in stat['lift']['per_bin']])
st = stat['lift']['stroke']
w('Stroke %d mm: comb %d to %d mm; starts %d mm below the lowest comb in the bin set; %d mm left above the highest comb plus lift.' % (st['stroke_mm'], st['comb_z_min_mm'], st['comb_z_max_mm'], st['start_below_lowest_mm'], st['top_reserve_above_highest_plus_lift_mm'])); w('')
table(['Member', 'Static stress MPa', 'Stress at 3 g MPa', 'Safety factor at 3 g (S235)'],
      [[k, v.get('stress_static_MPa', v.get('bearing_static_MPa')), v.get('stress_3g_MPa', v.get('bearing_3g_MPa')), v.get('sf_3g_S235', 'HDPE yield ' + str(v.get('hdpe_yield_MPa')) + ' MPa')] for k, v in stat['structure'].items()])
table(['Load', 'Mass kg', 'Sideways tip deg', 'Tip-back grade %', 'Nose share, flat %', 'Nose share on a 12 % climb %'],
      [[r['load'], r['mass_kg'], r['lateral_tip_deg'], r['tip_back_grade_pct'], r['nose_share_flat_pct'], r['nose_share_12pct_climb_pct']] for r in stat['stability']['rows']])

w('## 7. Docking tolerance model (`dock_mc.py`)'); w('')
w('%d draws per bin and case. %s **This is a tolerance stack that treats the comb as rigid; the float of the self-aligning comb is not modelled and this is not a substitute for G1.**' % (dock['n_per_bin'], dock['note'])); w('')
table(['Case', 'First try %', 'With one re-approach %'], [[k, v['mean_first_try_pct'], v['mean_with_retry_pct']] for k, v in dock['cases'].items()])
table(['Bin', 'Side clearance at the wheels mm', 'Funnel capture mm', 'Comb height mm', 'Lift reserve mm'],
      [[e['bin'], e['lateral_at_wheels_mm'], e['mouth_capture_mm'], e['comb_mm'], e['lift_reserve_mm']] for e in dock['envelope']])

w('## 8. Evenings, turning and placement (`mission.py`; estimate, not SITL)'); w('')
table(['Cruise m/s', 'Bins', 'Kind', 'Minutes', 'Wh', 'Within the %s Wh plan' % mis['evenings'][0]['battery_plan_wh']],
      [[e['v_cruise'], e['bins'], e['kind'], e['minutes'], e['wh'], e['within_plan']] for e in mis['evenings']])
t = mis['turning']['Rev H2 pivot']
w('Pivot circle %.2f m, set by the %s (frame alone %.2f m). Free margin %.2f m a side in the 3.6 m lane and %.2f m a side at the 2.9 m narrowing (s 500 to 516 m). %s'
  % (t['u_turn_width_m'], t['set_by'], t['frame_only_m'], t['free_side_margin_in_3p6m_lane_m'], t['margin_at_2p9m_narrowing_m'], mis['turning']['reference_other_agent_lanefit']['note'])); w('')
table(['Placement case', 'p50 mm', 'p95 mm', 'Yaw p95 deg', 'Over 0.6 m %'], [[k, v['p50_mm'], v['p95_mm'], v['yaw_p95_deg'], v['over_0p6m_pct']] for k, v in mis['placement']['cases'].items()])

w('## 9. Cost (`bom_revH2.py`)'); w('')
d, n = s['h2_donor'], s['h2_new']; b2 = s['b2_published']; b2c = s['b2_without_duplicate_actuator']
w('Basis: %s. Contingency by price status as in `bom_revG8.py` (checked 5 %%, excerpt 8 %%, estimate 12 %%, used or local 15 %%).' % s['basis']); w('')
table(['Design', 'Donor drive, all-in EUR', 'New drive, all-in EUR'], [
    ['B2 as published', b2['donor']['all_in'], b2['new']['all_in']],
    ['B2 without the duplicate lift actuator (to be confirmed by its authors)', b2c['donor'], b2c['new']],
    ['Rev H re-based by the other agent on the G8 baseline', s['revh_claim']['rebased_by_other_agent'], '-'],
    ['**Rev H2**', '**%.2f**' % d['all_in'], '**%.2f**' % n['all_in']],
    ['Rev H2 with the four gated savings (EUR %d of parts)' % s['gated_savings_parts'], s['h2_donor_with_gated_savings'], s['h2_new_with_gated_savings']]])
w('Rev H2 donor: parts %.2f + logistics %.2f + contingency %.2f, %d lines, %d %% of parts value price-checked. New drive: parts %.2f + logistics %.2f + contingency %.2f, %d lines.'
  % (d['parts'], d['logistics'], d['contingency'], d['lines'], d['price_checked_share_pct'], n['parts'], n['logistics'], n['contingency'], n['lines'])); w('')
w('The earlier Rev H figure of EUR %.0f all-in is withdrawn. It was built on the older G4 list and left out the G7/G8 safety, wiring and comms additions, as the other agent pointed out.' % s['revh_claim']['all_in']); w('')
areas = list(d['by_area'].keys())
table(['Area', 'Donor EUR', 'New drive EUR'], [[a, d['by_area'][a], n['by_area'].get(a, '-')] for a in areas])
table(['Gated saving (not in the totals)', 'EUR', 'Gate', 'Note'], s['gated_savings'])
table(['Safety item the research rated optional, kept anyway', 'EUR'], s['safety_items_rated_optional_by_research_not_taken'])
w('Donor price: %s. B2\'s list: %s' % (s['donor_price_sensitivity'], b2['duplicate_actuator']['note'])); w('')
w('Full lists: `results/bom_revH2_donor.csv`, `results/bom_revH2_new.csv`. Steel: `results/cut_list_revH2.csv`, `results/plate_list_revH2.csv`.'); w('')

w('## 10. What these results do not show'); w('')
for tt in ['Contact between comb and receiver, the bin swinging onto the pad, the bin leaving the comb, or the bin\'s wheels touching the ground: the bin is welded in this model. G1, G5, G6 and G7 of the frozen gate are open.',
           'Yaw: one-sided obstacle results are optimistic, and a jack-knife or slew on a step cannot appear.',
           'The full-width 40 mm step: this model passes it; the other agent\'s MuJoCo model stalls every design on it. Treat it as failing until a kerb test says otherwise.',
           'Software: no SITL run. Timings are from a kinematic model of the lane profile, checked against one Rev G SITL run.',
           'The real bins: front-wall position, receiver profile and lip strength are from drawings and the standard\'s public summaries, not from Brian\'s bins.',
           'Prices: %d %% of the donor-build parts value is price-checked; the rest are estimates or excerpts dated 11 and 12 November 2026.' % d['price_checked_share_pct']]:
    w('- ' + tt)
open(os.path.join(HERE, '..', 'RESULTS_H2.md'), 'w').write('\n'.join(L) + '\n')
print('wrote RESULTS_H2.md,', len(L), 'lines')
